3.1 Пример структуры affinity_db и bupar_db
-- ============================================================================
-- СХЕМА АНАЛИТИЧЕСКОЙ СУБД РЕКОМЕНДАЦИЙ (affinity_db)
-- ============================================================================
CREATE DATABASE affinity_db;
\c affinity_db;

-- 1. Таблица разреженной матрицы предпочтений групп
CREATE TABLE user_product_affinity (
    home_group_id VARCHAR(50) NOT NULL,
    master_product_id VARCHAR(50) NOT NULL,
    score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100),
    last_interaction TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    PRIMARY KEY (home_group_id, master_product_id)
);

-- 2. Локальный кэш-справочник базовых весов (Read-модель репликации из MDM)
CREATE TABLE affinity_product_reference (
    product_id VARCHAR(50) PRIMARY KEY,
    base_affinity_score INTEGER NOT NULL CHECK (base_affinity_score BETWEEN 0 AND 100)
);

-- Индекс для ночного Крон-движка деградации весов (03:00)
CREATE INDEX idx_affinity_cron_decay ON user_product_affinity (last_interaction ASC) WHERE score &gt; 10;

-- ============================================================================
-- СХЕМА АНАЛИТИЧЕСКОЙ СУБД PROCESS MINING (bupar_db)
-- ============================================================================
CREATE DATABASE bupar_db;
\c bupar_db;

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Плоский журнал логов событий (Event Log) для Process Mining
CREATE TABLE bupar_event_logs (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id VARCHAR(50) NOT NULL, -- Сквозной маркер партии/цепочки еды
    trace_id VARCHAR(50) NOT NULL, -- Ссылка на технический UUID трейсинга логов Loki
    home_group_id VARCHAR(50) NOT NULL,
    activity_name VARCHAR(100) NOT NULL, -- Шаги: PRODUCT_BATCH_PURCHASED, MANUAL_DISH_COOKED, FOOD_CONSUMED, FOOD_WASTED
    payload_details JSONB NOT NULL, -- Слепок физических параметров мутации
    event_timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Композитный индекс: критически важен для пакета bupar при сборке хронологических графов
CREATE INDEX idx_bupar_case_id_timeline ON bupar_event_logs(case_id, event_timestamp ASC);
-- Индекс для мгновенной фильтрации технического следа по trace_id шлюза Nginx
CREATE INDEX idx_bupar_logs_trace_id ON bupar_event_logs(trace_id);

