Пояснение: Поскольку аргументы обнуленных интентов сдвинулись относительно максимума (\(0 - 1.015 = -1.015\)), их экспоненты дали значения \(e^{-1.015} \approx 0.3624\). Экспонента покупки дала \(e^0 = 1.0\). Общая сумма равен \(1.0 + 0.3624 + 0.3624 + 0.3624 = 2.0872\). Доля покупки: \(1.0 / 2.0872 = 0.4791\) (остальные три варианта делят остаток поровну), математика сбалансирована.

5. Программный прототип реализации (Python)
import numpy as np
from uuid import UUID

class StochasticRiskGenerator:
    def __init__(self):
        self.intents = ["INVENTORY", "PREPARING", "CONSUME", "WASTE"]

    def logistic_normalization(self, x: float) -&gt; float:
        return 1 / (1 + np.exp(-x))

    def project_stochastic_seed(self, p_vector: list) -&gt; str:
        xi = np.random.uniform(0.0, 1.0)
        cumulative_probabilities = np.cumsum(p_vector)
        chosen_index = np.searchsorted(cumulative_probabilities, xi)
        return self.intents[chosen_index]

